<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, action } from '../api'
const candidates=ref<any[]>([]),published=ref<any[]>([]),name=ref(''),description=ref(''),body=ref(''),paths=ref(''),evidence=ref(''),result=ref<any>(null),pending=ref<any>(null),busy=ref(false),creating=ref(false)
async function operation(p:any){return api('/governance/assistant_skill','POST',{parameters:p})}
async function load(){candidates.value=(await operation({action:'list'})).candidates;published.value=(await operation({action:'published'})).items}
async function run(p:any){busy.value=true;await action(async()=>{result.value=await operation(p);pending.value=['create','publish','remove'].includes(p.action)&&!p.confirm?p:null;await load()},'处理完成');busy.value=false}
async function create(){await run({action:'create',name:name.value,description:description.value,body:body.value,source_paths:paths.value.split('\n').map(s=>s.trim()).filter(Boolean)})}
async function publish(item:any){await run({action:'publish',name:item.name,evidence_refs:evidence.value.split('\n').map(s=>s.trim()).filter(Boolean)})}
async function download(item:any){await action(async()=>{const value=await operation({action:'export',name:item.name});const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=item.name+'.json';a.click();URL.revokeObjectURL(url)},'Skill 已导出')}
onMounted(()=>action(load,''))
</script>
<template><div class="page-title"><div><h1>Skill 管理</h1><p>资料提取、候选审阅、完整性校验与发布；发布需要任务验证引用。</p></div><button class="primary" @click="creating=!creating">{{creating?'收起':'创建候选'}}</button></div><form v-if="creating" class="form-panel" @submit.prevent="create"><label>名称<input v-model="name" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" required placeholder="例如 project-review"></label><label>适用场景<input v-model="description" required></label><label>来源文件或目录（每行一个）<textarea v-model="paths" required placeholder="已登记项目、Wiki 或受管知识目录的路径"></textarea></label><div class="actions"><button type="button" :disabled="busy" @click="run({action:'analyze',source_paths:paths.split('\n').filter(Boolean)})">分析来源</button><button type="button" :disabled="busy" @click="run({action:'extract',source_paths:paths.split('\n').filter(Boolean)})">提取资料</button></div><label>Skill 正文<textarea v-model="body" rows="10" required placeholder="操作方法、决策规则、验证步骤与适用边界"></textarea></label><button class="primary" :disabled="busy">生成候选预览</button></form><section class="form-panel"><h2>候选 Skill</h2><p v-if="!candidates.length" class="muted">暂无候选。先分析来源资料，再编写 Skill 内容。</p><label>发布验证引用（每行一个）<textarea v-model="evidence" placeholder="Memory Center 任务、引用或验证记录"></textarea></label><table v-if="candidates.length"><thead><tr><th>名称</th><th>来源数</th><th>操作</th></tr></thead><tbody><tr v-for="item in candidates" :key="item.name"><td>{{item.name}}</td><td>{{item.source_count}}</td><td class="actions"><button @click="run({action:'inspect',name:item.name})">审阅</button><button @click="run({action:'validate',name:item.name})">校验</button><button @click="publish(item)">发布预览</button><button @click="download(item)">导出</button><button @click="run({action:'remove',name:item.name})">移除</button></td></tr></tbody></table></section><section class="form-panel"><h2>已启用 Skill</h2><p class="muted">默认保存在服务数据目录；配置共享 Skill 目录后，发布内容可供宿主直接发现。</p><p v-if="!published.length">暂无已启用 Skill。</p><table v-else><thead><tr><th>名称</th><th>来源</th><th>操作</th></tr></thead><tbody><tr v-for="item in published" :key="item.name"><td>{{item.name}}</td><td>{{item.publication?'受管发布':'已有 Skill'}}</td><td><button @click="run({action:'remove',name:item.name,published:true})">停用</button></td></tr></tbody></table></section><section v-if="result" class="form-panel"><h2>审阅结果</h2><pre class="result-text">{{JSON.stringify(result,null,2)}}</pre><button v-if="pending" class="primary" :disabled="busy" @click="run({...pending,confirm:true})">确认{{pending.action==='publish'?'发布':pending.action==='remove'?'移除':'创建'}}</button></section></template>
